using System.Collections;
using FMODUnity;
using LittleLeo;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea;

public class CorruptedAnimalOverCorruption : ZoomableInstance
{
	[Header("OverCorruption Shake")]
	[SerializeField]
	private float shakeDuration;

	[SerializeField]
	private float shakePower;

	[SerializeField]
	private float corruptedAnimalShakePower;

	[Header("Components")]
	[SerializeField]
	private CorruptionStats corruptionStats;

	[SerializeField]
	private GameObject corruptedAnimalGo;

	[SerializeField]
	private GameObject overCorruptedFeedbackPrefab;

	[SerializeField]
	private CorruptedAnimalSpriteControl corruptedAnimalSpriteControl;

	[SerializeField]
	private ActionFaceInstance2D actionFaceInstance2D;

	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private MapHandler mapHandler;

	[SerializeField]
	private UnitDialogue unitDialogue;

	[SerializeField]
	private Transform overCorruptionGauge;

	[Header("Tooltip")]
	[SerializeField]
	private GameObjectReference actionDescriptionActionOwnerReference;

	[Header("SFX")]
	[SerializeField]
	private EventReference genericOverCorruptSFX;

	[Header("Difficulty Level")]
	[SerializeField]
	private DifficultyLevels difficultyLevels;

	private OverCorruptionAction overCorruptionAction;

	private CorruptedAnimalData corruptedAnimalData;

	private bool ignoreNextOverCorruption;

	public void Initialize(CorruptedAnimalData corruptedAnimalData)
	{
		this.corruptedAnimalData = corruptedAnimalData;
		int currentDifficultyLevelModifyEnemiesHighestIndex = difficultyLevels.GetCurrentDifficultyLevelModifyEnemiesHighestIndex();
		if (corruptedAnimalData.OverCorruptionActionList.Count > currentDifficultyLevelModifyEnemiesHighestIndex)
		{
			overCorruptionAction = corruptedAnimalData.OverCorruptionActionList[currentDifficultyLevelModifyEnemiesHighestIndex];
		}
		else
		{
			overCorruptionAction = corruptedAnimalData.OverCorruptionActionList.Last();
		}
		actionFaceInstance2D.Initialize(overCorruptionAction.BattleAction, overCorruptionAction.ValueText(overCorruptionAction.ActionAmount), empowered: false);
	}

	public void Initialize(OverCorruptionAction overCorruptionAction)
	{
		this.overCorruptionAction = overCorruptionAction;
		actionFaceInstance2D.Initialize(overCorruptionAction.BattleAction, overCorruptionAction.ValueText(overCorruptionAction.ActionAmount), empowered: false);
	}

	public override void InitializeActionDescriptionPanel()
	{
		actionDescriptionActionOwnerReference.Set(corruptedAnimalGo);
		actionDescriptionPanel.Initialize(overCorruptionAction);
	}

	public IEnumerator OverCorruptedCoroutine()
	{
		Debug.Log("OverCorruptedCoroutine: Start");
		if (mapHandler.CorruptionSourceBattle && currentCorruptedAnimals.GetCorruptionSource() == null)
		{
			Debug.Log("mapHandler.CorruptionSourceBattle && currentCorruptedAnimals.GetCorruptionSource() == null");
			yield return null;
		}
		else if (!corruptionStats.IsDefeated() && currentCorruptedAnimals.IsAnyEnemyActive() && !ignoreNextOverCorruption)
		{
			Debug.Log("corruptionStats.CurrentCorruption > 0");
			if (unitDialogue.HasDialogueTypeShowDialogueBoxRandomDialogue(DialogueTypeEnum.OVERCORRUPTION))
			{
				yield return new WaitForSeconds(2f);
			}
			else
			{
				yield return new WaitForSeconds(1f);
			}
			ReferenceSingleton<PoolHandler>.Instance.GetObject(overCorruptedFeedbackPrefab.name).GetComponent<OverCorruptedFeedback>().PlayOverCorruptedFeedback(corruptedAnimalGo.transform.position);
			ShakeOverCorruptionAction();
			ShakeCorruptedAnimal();
			PlayOverCorruptSFX();
			Debug.Log("OverCorruptedCoroutine: Feedback");
			yield return new WaitForSeconds(1.1f);
			Debug.Log("OverCorruptedCoroutine: ActivateOvercorrupt");
			AnimationType animationType = AnimationType.Attack;
			if ((bool)corruptedAnimalData.AnimationData)
			{
				if (corruptedAnimalData.AnimationData.EnableCustomOverCorruptionAnimation)
				{
					animationType = corruptedAnimalData.AnimationData.OverCorruptionAnimationType;
				}
				else if (corruptedAnimalData.AnimationData.EnableCustomOverCorruptionAnimationComplex)
				{
					animationType = corruptedAnimalData.AnimationData.GetCustomOvercorruptAnimationType(corruptedAnimalSpriteControl, corruptedAnimalData.EnemySFXData);
				}
			}
			yield return ReferenceSingleton<CoroutineHandler>.Instance.StartCoroutine(corruptedAnimalSpriteControl.PlayAttackAnimation(animationType, delegate
			{
				overCorruptionAction.BattleAction.enemyActionLogic.ActivateAction(overCorruptionAction.BattleAction, overCorruptionAction.ActionAmount, corruptedAnimalGo);
			}, overCorruption: true));
			Debug.Log("OverCorruptedCoroutine: End");
		}
		else
		{
			Debug.Log("corruptionStats.CurrentCorruption <= 0: " + corruptionStats.CurrentCorruption);
		}
		ignoreNextOverCorruption = false;
	}

	private void ShakeCorruptedAnimal()
	{
		CoroutineUtility.ShakeRoutine(this, corruptedAnimalSpriteControl.AnimationSkeletonTransform, shakeDuration, corruptedAnimalShakePower);
	}

	public void ShakeOverCorruptionAction()
	{
		CoroutineUtility.ShakeRoutine(this, base.transform, shakeDuration, shakePower);
	}

	public void ShakeOverCorruptionGauge()
	{
		CoroutineUtility.ShakeRoutine(this, overCorruptionGauge, shakeDuration, shakePower);
	}

	private void PlayOverCorruptSFX()
	{
		EnemySFXData enemySFXData = corruptedAnimalData.EnemySFXData;
		if ((bool)enemySFXData)
		{
			if (enemySFXData.EnableOverCorrupt)
			{
				ReferenceSingleton<SFXHandler>.Instance.PlaySFX(enemySFXData.OverCorrupt);
			}
			else if (enemySFXData.EnableCustomOverCorrupt)
			{
				enemySFXData.CustomEnemySFXData.PlayCustomOverCorruptionSFX();
			}
			else
			{
				ReferenceSingleton<SFXHandler>.Instance.PlaySFX(genericOverCorruptSFX);
			}
		}
		else
		{
			ReferenceSingleton<SFXHandler>.Instance.PlaySFX(genericOverCorruptSFX);
		}
	}

	public void IgnoreNextOverCorruption()
	{
		ignoreNextOverCorruption = true;
	}
}
